import { useState, useEffect, useContext } from "react";
import { useNavigate } from "react-router-dom";
import { AuthContext } from "../contexts/AuthContext";
import api from "../api";
import {
  BarChart3,
  Users,
  FileText,
  Vote,
  LogOut,
  UserCheck,
  UserX,
  Trash2,
} from "lucide-react";

export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");
  const [results, setResults] = useState({});
  const [winners, setWinners] = useState({});

  const { logout, token } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    } else {
      alert(err.response?.data?.error || err.message);
    }
  };

  const fetchVotingState = async () => {
    try {
      const res = await api.get("/admin/voting-state");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      handleApiError(err);
    }
  };
  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/admin/pending-users");
      setPendingUsers(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };
  const fetchCandidates = async () => {
    try {
      const res = await api.get("/admin/candidates");
      setCandidates(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };
  const fetchLogs = async () => {
    try {
      const res = await api.get("/admin/logs");
      setLogs(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };
  const fetchResults = async () => {
    try {
      const res = await api.get("/admin/results");
      setResults(res.data.positionResults);
      setWinners(res.data.winners);
    } catch (err) {
      handleApiError(err);
    }
  };

  const toggleVoting = async () => {
    try {
      const res = await api.post("/admin/toggle-voting");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      handleApiError(err);
    }
  };
  const approveUser = async (id) => {
    try {
      await api.post(`/admin/approve-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };
  const rejectUser = async (id) => {
    try {
      await api.post(`/admin/reject-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };
  const deleteCandidate = async (id) => {
    if (!window.confirm("Delete this candidate?")) return;
    try {
      await api.delete(`/admin/candidates/${id}`);
      fetchCandidates();
    } catch (err) {
      handleApiError(err);
    }
  };
  const generateReport = async () => {
    try {
      const res = await api.post("/admin/generate-report");
      setReportHash(res.data.hash);
    } catch (err) {
      handleApiError(err);
    }
  };

  useEffect(() => {
    if (!token) {
      navigate("/login");
      return;
    }
    const init = async () => {
      await fetchVotingState();
      await fetchPendingUsers();
      await fetchCandidates();
      await fetchLogs();
      await fetchResults();
    };
    init();
  }, [token]);

  return (
    <div className="min-h-screen flex bg-gray-50">
      {/* Sidebar */}
      <aside className="w-64 bg-gradient-to-b from-blue-900 to-blue-700 text-white shadow-lg flex flex-col">
        <div className="p-6 text-2xl font-bold border-b border-blue-600">
          iVote Admin
        </div>
        <nav className="flex-1 p-4 space-y-4">
          <div className="flex items-center gap-2 text-gray-200">
            <Vote size={18} /> Voting
          </div>
          <div className="flex items-center gap-2 text-gray-200">
            <Users size={18} /> Users
          </div>
          <div className="flex items-center gap-2 text-gray-200">
            <BarChart3 size={18} /> Results
          </div>
          <div className="flex items-center gap-2 text-gray-200">
            <FileText size={18} /> Reports
          </div>
        </nav>
        <button
          onClick={() => {
            logout();
            navigate("/login");
          }}
          className="flex items-center justify-center gap-2 p-4 bg-red-600 hover:bg-red-700 transition-colors"
        >
          <LogOut size={18} /> Logout
        </button>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-8 space-y-8">
        {/* Voting Status */}
        <div className="bg-white rounded-xl shadow-md p-6 flex items-center justify-between">
          <div>
            <h2 className="text-xl font-semibold">Voting Status</h2>
            <p
              className={`mt-1 font-medium ${
                votingOpen ? "text-green-600" : "text-red-600"
              }`}
            >
              {votingOpen ? "Open" : "Closed"}
            </p>
          </div>
          <button
            onClick={toggleVoting}
            className={`px-6 py-2 rounded-lg font-semibold text-white shadow ${
              votingOpen
                ? "bg-red-600 hover:bg-red-700"
                : "bg-green-600 hover:bg-green-700"
            }`}
          >
            {votingOpen ? "Close Voting" : "Open Voting"}
          </button>
        </div>

        {/* Pending Users */}
        <div className="bg-white rounded-xl shadow-md p-6">
          <h2 className="text-xl font-semibold mb-4 flex items-center gap-2">
            <Users size={20} /> Pending Registrations
          </h2>
          {pendingUsers.length === 0 ? (
            <p className="text-gray-500">No pending users.</p>
          ) : (
            <table className="w-full text-sm border border-gray-200 rounded-lg overflow-hidden">
              <thead className="bg-gray-100 text-gray-700 sticky top-0">
                <tr>
                  <th className="px-4 py-2 text-left">Student Number</th>
                  <th className="px-4 py-2 text-left">Name</th>
                  <th className="px-4 py-2 text-left">Email</th>
                  <th className="px-4 py-2 text-center">Actions</th>
                </tr>
              </thead>
              <tbody>
                {pendingUsers.map((user) => (
                  <tr
                    key={user.id}
                    className="border-t hover:bg-gray-50 transition"
                  >
                    <td className="px-4 py-2">{user.studentNumber}</td>
                    <td className="px-4 py-2">{user.name}</td>
                    <td className="px-4 py-2">{user.email}</td>
                    <td className="px-4 py-2 flex justify-center gap-2">
                      <button
                        onClick={() => approveUser(user.id)}
                        className="flex items-center gap-1 px-3 py-1 bg-green-600 text-white rounded hover:bg-green-700"
                      >
                        <UserCheck size={16} /> Approve
                      </button>
                      <button
                        onClick={() => rejectUser(user.id)}
                        className="flex items-center gap-1 px-3 py-1 bg-red-600 text-white rounded hover:bg-red-700"
                      >
                        <UserX size={16} /> Reject
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>

        {/* Candidates */}
        <div className="bg-white rounded-xl shadow-md p-6">
          <h2 className="text-xl font-semibold mb-4">Candidates</h2>
          <table className="w-full text-sm border border-gray-200">
            <thead className="bg-gray-100 text-gray-700">
              <tr>
                <th className="px-4 py-2 text-left">Name</th>
                <th className="px-4 py-2 text-left">Position</th>
                <th className="px-4 py-2 text-left">Party</th>
                <th className="px-4 py-2 text-center">Actions</th>
              </tr>
            </thead>
            <tbody>
              {candidates.map((c) => (
                <tr
                  key={c.id}
                  className="border-t hover:bg-gray-50 transition"
                >
                  <td className="px-4 py-2">{c.name}</td>
                  <td className="px-4 py-2">{c.position}</td>
                  <td className="px-4 py-2">{c.party || "-"}</td>
                  <td className="px-4 py-2 text-center">
                    <button
                      onClick={() => deleteCandidate(c.id)}
                      className="flex items-center gap-1 px-3 py-1 bg-red-600 text-white rounded hover:bg-red-700"
                    >
                      <Trash2 size={16} /> Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Results */}
        <div className="bg-white rounded-xl shadow-md p-6">
          <h2 className="text-xl font-semibold mb-4 flex items-center gap-2">
            <BarChart3 size={20} /> Election Results
          </h2>
          {Object.keys(results).length === 0 ? (
            <p className="text-gray-500">No results available yet.</p>
          ) : (
            Object.keys(results).map((pos) => (
              <div key={pos} className="mb-6">
                <h3 className="text-lg font-bold mb-2">{pos}</h3>
                <table className="w-full text-sm border border-gray-200">
                  <thead className="bg-gray-100 text-gray-700">
                    <tr>
                      <th className="px-4 py-2 text-left">Name</th>
                      <th className="px-4 py-2 text-left">Party</th>
                      <th className="px-4 py-2 text-center">Votes</th>
                      <th className="px-4 py-2 text-center">Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {results[pos].map((c) => (
                      <tr
                        key={c.id}
                        className="border-t hover:bg-gray-50 transition"
                      >
                        <td className="px-4 py-2">{c.name}</td>
                        <td className="px-4 py-2">{c.party || "-"}</td>
                        <td className="px-4 py-2 text-center">{c.votes}</td>
                        <td className="px-4 py-2 text-center font-semibold">
                          {winners[pos]?.id === c.id ? (
                            <span className="text-green-600">Winner</span>
                          ) : (
                            <span className="text-gray-500">—</span>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ))
          )}
        </div>

        {/* Reports */}
        <div className="bg-white rounded-xl shadow-md p-6 flex flex-col gap-4">
          <h2 className="text-xl font-semibold flex items-center gap-2">
            <FileText size={20} /> Reports
          </h2>
          <button
            onClick={generateReport}
            className="self-start px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
          >
            Generate Final Report
          </button>
          {reportHash && (
            <p className="text-gray-600">
              Cryptographic Hash:{" "}
              <span className="font-mono text-sm">{reportHash}</span>
            </p>
          )}
        </div>

        {/* Logs */}
        <div className="bg-white rounded-xl shadow-md p-6">
          <h2 className="text-xl font-semibold mb-4">System Logs</h2>
          {logs.length === 0 ? (
            <p className="text-gray-500">No logs available.</p>
          ) : (
            <ul className="space-y-2 max-h-64 overflow-y-auto">
              {logs.map((log) => (
                <li key={log.id} className="text-gray-700">
                  {log.action}{" "}
                  <span className="text-gray-400 text-sm">
                    {new Date(log.createdAt).toLocaleString()}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </div>
      </main>
    </div>
  );
}
